<template><Card class="s3-manager"><header class="header"><div><h2>商城订单详情</h2><p>订单与履约记录只读监管</p></div><Button @click="back">返回订单列表</Button></header><Alert v-if="error" type="error" show-icon>{{error}} <Button type="text" @click="load">重新读取</Button></Alert><Spin v-if="loading" fix/><template v-if="order">
<DetailSection title="交易与子单摘要"><FieldRow label="店铺">{{order.storeName}}</FieldRow><FieldRow label="子单编号">{{order.orderSn}}</FieldRow><FieldRow label="所属合单">{{order.tradeSn}}</FieldRow><FieldRow label="履约方式">{{label(order.method)}}</FieldRow><FieldRow label="付款">{{label(order.paymentStatus)}}</FieldRow><FieldRow label="履约">{{label(order.phase)}}</FieldRow><FieldRow label="创建时间">{{date(order.createdAt)}}</FieldRow><FieldRow label="完成时间">{{date(order.completedAt)}}</FieldRow></DetailSection>
<Alert v-if="order.blockedReason" type="warning" show-icon>当前交接或操作条件未满足，请结合付款事实、原订单与异常记录核实。</Alert>
<DetailSection title="商品与金额"><div class="table-scroll wide"><Table :data="order.items" :columns="itemColumns"><template slot="unit" slot-scope="{row}">{{money(row.unitPriceCent)}}</template></Table></div><FieldRow label="商品金额">{{money(order.goodsCent)}}</FieldRow><FieldRow label="配送 / 物流费">{{money(order.freightCent)}}</FieldRow><FieldRow label="订单金额">{{money(order.amountCent)}}</FieldRow><FieldRow label="实际付款">{{money(order.paidAmountCent)}}</FieldRow><FieldRow label="实际付款时间">{{date(order.paidAt)}}</FieldRow></DetailSection>
<DetailSection title="成交时收货与点位快照"><FieldRow label="联系人">{{order.contact.name}} {{order.contact.mobile}}</FieldRow><FieldRow v-if="order.address" label="收货地址">{{order.address.region}} {{order.address.detail}}</FieldRow><template v-if="order.point"><FieldRow label="点位">{{order.point.name}}</FieldRow><FieldRow label="点位地址">{{order.point.address}}</FieldRow><FieldRow label="点位须知">{{order.point.instructions||'未填写'}}</FieldRow></template><FieldRow label="买家留言">{{order.buyerRemark||'无'}}</FieldRow></DetailSection>
<DetailSection v-if="order.method==='EXPRESS'" title="发货记录"><FieldRow label="物流公司">{{order.logistics.company||'尚未发货'}}</FieldRow><FieldRow label="运单号">{{order.logistics.number||'未登记'}}</FieldRow><FieldRow label="发货时间">{{date(order.logistics.shippedAt)}}</FieldRow></DetailSection>
<DetailSection title="履约轨迹与异常"><div class="wide"><p v-if="!order.timeline.length" class="meta">暂无履约事件。</p><div v-for="event in order.timeline" :key="event.type+event.at" class="timeline"><strong>{{label(event.type)}}</strong><span>{{date(event.at)}}</span><span>{{event.actorDomain==='RESIDENT'?'居民本人':event.actorDomain==='STORE'?'商户':'系统'}} {{event.actorId||''}}</span></div><div v-for="event in order.exceptions" :key="event.at" class="exception"><strong>履约异常</strong><p>{{event.reason}}</p><span>{{date(event.at)}}</span></div></div></DetailSection>
</template></Card></template>
<script>
import {stage3Read} from '@/api/stage3';import {managerSession} from '@/libs/manager-session';import DetailSection from '../p0-stage1/usability/components/DetailSection';import FieldRow from '../p0-stage1/usability/components/FieldRow';import {money,date,label} from './presentation.cjs';
export default{components:{DetailSection,FieldRow},data(){return {order:null,error:'',loading:false,ticket:0,itemColumns:[{title:'商品',key:'name',minWidth:220},{title:'规格',key:'specifications',minWidth:160},{title:'数量',key:'quantity',width:85},{title:'单价',slot:'unit',width:120}]}},mounted(){this.load()},beforeDestroy(){this.ticket++},watch:{'$route.params.id'(){this.order=null;this.load()}},methods:{money,date,label,back(){this.$router.push({path:'/s3/orders',query:this.$route.query})},async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.order=null;this.loading=true;this.error='';try{const v=await stage3Read('/orders/'+this.$route.params.id);if(ticket===this.ticket&&managerSession.sameSession(owner))this.order=v}catch(e){if(ticket===this.ticket)this.error=e.message}finally{if(ticket===this.ticket)this.loading=false}}}};
</script><style lang="scss">@import './stage3.scss';</style>
